{
  "root_cause": "The Govuk radios component only updates ARIA attributes and conditional visibility on click events. Keyboard arrow navigation changes the checked state of radio buttons without firing a click event, so the associated conditional content remains visible when it should be hidden.",
  "repair_strategy": "Add a 'change' event listener to the radios module that invokes the same attribute-update logic as the click handler, ensuring that any change to a radio's checked state (whether via mouse, keyboard, or other input) correctly shows or hides its associated conditional content.",
  "edits": [
    {
      "path": "src/govuk/components/radios/radios.js",
      "sha256": "a5f3970a55a7d3dd59bfdfb0ef82c8f9f8fd2ace3eefa606ec486fb263e86b8c",
      "before": "  // Handle events
  $module.addEventListener('click', this.handleClick.bind(this))
}

Radios.prototype.setAttributes = function ($input) {
  var inputIsChecked = $input.checked
  $input.setAttribute('aria-expanded', inputIsChecked)

  var $content = this.$module.querySelector('#' + $input.getAttribute('aria-controls'))
  if ($content) {
    $content.classList.toggle('govuk-radios__conditional--hidden', !inputIsChecked)
  }
}

Radios.prototype.handleClick = function (event) {
  nodeListForEach(this.$inputs, function ($input) {
    // If a radio with aria-controls, handle click
    var isRadio = $input.getAttribute('type') === 'radio'
    var hasAriaControls = $input.getAttribute('aria-controls')
    if (isRadio && hasAriaControls) {
      this.setAttributes($input)
    }
  }.bind(this))
}

export default Radios",
      "after": "  // Handle events
  $module.addEventListener('click', this.handleClick.bind(this))
  $module.addEventListener('change', this.handleChange.bind(this))
}

Radios.prototype.setAttributes = function ($input) {
  var inputIsChecked = $input.checked
  $input.setAttribute('aria-expanded', inputIsChecked)

  var $content = this.$module.querySelector('#' + $input.getAttribute('aria-controls'))
  if ($content) {
    $content.classList.toggle('govuk-radios__conditional--hidden', !inputIsChecked)
  }
}

Radios.prototype.handleClick = function (event) {
  nodeListForEach(this.$inputs, function ($input) {
    // If a radio with aria-controls, handle click
    var isRadio = $input.getAttribute('type') === 'radio'
    var hasAriaControls = $input.getAttribute('aria-controls')
    if (isRadio && hasAriaControls) {
      this.setAttributes($input)
    }
  }.bind(this))
}

Radios.prototype.handleChange = function (event) {
  nodeListForEach(this.$inputs, function ($input) {
    // If a radio with aria-controls, handle change
    var isRadio = $input.getAttribute('type') === 'radio'
    var hasAriaControls = $input.getAttribute('aria-controls')
    if (isRadio && hasAriaControls) {
      this.setAttributes($input)
    }
  }.bind(this))
}

export default Radios"
    }
  ],
  "expected_accessibility_effect": "Keyboard navigation via arrow keys will now correctly show or hide conditional fields, satisfying WCAG 2.1.1 (Keyboard), 2.4.3 (Focus Order), and 4.1.2 (Name, Role, Value).",
  "functional_risks": [
    "Both click and change events may fire for the same user interaction, causing duplicate attribute updates; however, the outcome is idempotent and harmless.",
    "The change listener will only affect radio inputs that have an aria-controls attribute, leaving other form controls unaffected."
  ],
  "verification_requirements": [
    "Verify that pressing ArrowDown from the Text message radio hides the mobile number field when moving to the opt-out radio.",
    "Verify that pressing ArrowUp from the opt-out radio shows the mobile number field when moving back to the Text message radio.",
    "Verify that mouse clicks on radios continue to show/hide conditionals correctly.",
    "Verify that the existing regression guard (choose email via keyboard and enter address) still passes.",
    "Verify that form data reflects the selected radio value after keyboard navigation."
  ]
}
